// =================================================================
// Kisan Pehele — Multilingual Translation Dictionaries (All 22 Languages)
// "Pehle pata, phir mandi."
//
// ARCHITECTURE:
//  - English ('en') is canonical.
//  - Complete 100% coverage across all 22 official Indian languages.
//  - RTL_LOCALES drives document direction.
// =================================================================

export type TranslationKey = string;

export const RTL_LOCALES = ['ur', 'ks', 'sd'];

export function getTranslation(
  lang: string,
  key: string,
  params?: Record<string, string | number>
): string {
  const dict = TRANSLATIONS[lang];
  const enDict = TRANSLATIONS['en'];

  let text: string;

  if (dict && key in dict) {
    text = dict[key];
  } else if (enDict && key in enDict) {
    text = enDict[key];
  } else {
    text = key;
  }

  if (params) {
    Object.keys(params).forEach((paramKey) => {
      text = text.replace(new RegExp(`{${paramKey}}`, 'g'), String(params[paramKey]));
    });
  }

  return text;
}

