    "for_centers.title": "Solutions for Procurement Centers & Mandi Operators",
    "for_centers.subtitle": "Accurate arrival forecasting, throughput pacing, digital weighing entry, and dispute-free daily procurement control.",
    "for_centers.feat_pacing_title": "Queue Throughput Pacing",
    "for_centers.feat_pacing_desc": "Farmers are called to the mandi based on real scale processing speeds, preventing vehicular congestion in the yard.",
    "for_centers.feat_weighing_title": "Paperless Weighing & Receipts",
    "for_centers.feat_weighing_desc": "Direct data capture from electronic scales and digital acceptance slips, eliminating manual errors and paperwork.",
    "for_centers.feat_audit_title": "Immutable Audit Integrity",
    "for_centers.feat_audit_desc": "Every entry is secured with the officer's digital ID and timestamp, ensuring 100% audit authenticity.",
    "for_centers.cta_btn": "📋 Mandi Officer & Staff Portal",
    "for_government.badge": "Government & Administration (District, State & National)",
    "for_government.title": "100% Transparent Procurement Oversight for Administration",
    "for_government.subtitle": "Real-time district-wise arrival analysis, anomaly detection, and automated policy reporting.",
    "for_government.feat_dashboard_title": "Live District Dashboard",
    "for_government.feat_dashboard_desc": "Monitor farmer turnout, quintals procured, and DBT status for every procurement center on a single screen.",
    "for_government.feat_alerts_title": "Anomaly & Security Alerts",
    "for_government.feat_alerts_desc": "Unusual patterns, such as repeated vehicle entries or abnormal moisture levels, are flagged instantly by the system.",
    "for_government.feat_reports_title": "Audit & Policy Reports",
    "for_government.feat_reports_desc": "Generate digitally verified data exports and compliance reports aligned with Ministry and CAG standards.",
    "for_government.cta_btn": "🏛️ District Collector & Admin Portal",
    "for_farmers.badge": "Farmer-First Platform (Annadata Empowerment)",
    "for_farmers.title": "Exclusive Benefits of 'Kisan Pehele' for Farmers",
    "for_farmers.subtitle": "Our mission is to eliminate mandi queues, ensure fair crop pricing, and empower every farmer with digital dignity.",
    "for_farmers.pillar1_title": "1. Voice Assistant in 22 Indian Languages (Voice AI)",
    "for_farmers.pillar1_desc": "No typing required. Book slots, check tokens, or verify mandi crowd status simply by speaking in your native language (Hindi, Odia, Punjabi, Bengali, Telugu, etc.).",
    "for_farmers.pillar1_quote": "“I need a token to sell paddy tomorrow morning at 10 AM”",
    "for_farmers.pillar2_title": "2. Guaranteed Digital Token & Transparent Queue",
    "for_farmers.pillar2_desc": "Receive an assured token number like A-142 and recommended arrival time upon booking. Live queue tracking keeps you updated via SMS.",
    "for_farmers.pillar2_tag": "✓ No Queue Jumping • Guaranteed Turn For Every Farmer",
    "for_farmers.pillar3_title": "3. IVR & Instant SMS on Feature Keypad Phones",
    "for_farmers.pillar3_desc": "No smartphone or internet needed. Dial 1800-180-1551 toll-free, press 1, and get token time and queue status. Receive instant SMS confirmations.",
    "for_farmers.pillar3_tag": "✓ No Internet Needed • 100% Rural Accessibility",
    "for_farmers.pillar4_title": "4. Trusted Helper Authorization",
    "for_farmers.pillar4_desc": "Elderly, unwell, or busy farmers can authorize a family member or trusted helper via OTP/QR to deliver produce, while payment goes directly to the farmer's account.",
    "for_farmers.pillar4_tag": "✓ Family Member Delivers • Payment Directly to Farmer's Bank",
    "for_farmers.rights_title": "Kisan Pehele — Your 5 Fundamental Rights (Farmer Bill of Rights)",
    "for_farmers.right1_title": "1. Respect for Time",
    "for_farmers.right1_desc": "Arrive at your scheduled slot, guaranteed weighing within 20 minutes.",
    "for_farmers.right2_title": "2. Accurate Weight & Moisture",
    "for_farmers.right2_desc": "Live readings from digital scales and moisture meters recorded on the receipt.",
    "for_farmers.right3_title": "3. Zero Intermediaries",
    "for_farmers.right3_desc": "100% protection from middlemen and commission agents, direct government procurement.",
    "for_farmers.right4_title": "4. Direct DBT Bank Payment",
    "for_farmers.right4_desc": "MSP amount transferred directly to your bank account within 24-48 hours.",
    "for_farmers.right5_title": "5. 24x7 Helpline Support",
    "for_farmers.right5_desc": "Instant resolution of any grievance or query via 1800-180-1551.",
    "for_farmers.right_link": "Open Farmer Account Now →",
    "for_farmers.cta_btn": "🌾 Enter Farmer Portal (Farmer Login)",
    "how_it_works.badge": "Architecture & Technical Workflow",
    "how_it_works.title": "How Kisan Pehele Works",
    "how_it_works.subtitle": "A complete walkthrough of cloud architecture, concurrent-safe token locking, radar queue intelligence, and automated bank DBT.",
    "how_it_works.arch1_title": "1. Idempotent Concurrent Slotting",
    "how_it_works.arch1_desc": "Row-level locking at the database level ensures no two farmers are ever assigned the same token slot during peak arrival surges.",
    "how_it_works.arch2_title": "2. Queue Pacing Algorithm",
    "how_it_works.arch2_desc": "Predictive arrival forecasting dynamically aligned with weighbridge processing speeds (e.g., 8 mins per trolley) and live SMS updates.",
    "how_it_works.arch3_title": "3. Automated PFMS DBT Pipeline",
    "how_it_works.arch3_desc": "Digitally signed weighment and moisture slips transmit directly to treasury and banking servers for 24-48 hour disbursement.",
    "how_it_works.timeline_heading": "Step-by-Step 5-Stage Procurement Process",
    "how_it_works.step1_title": "1. Center Discovery & Predictive Capacity",
    "how_it_works.step1_subtitle": "GPS-based location search and mandi load balancing",
    "how_it_works.step1_desc": "Farmers view active procurement centers across the district. The system analyzes daily capacity, active weigh scales, and current waiting queues to recommend the fastest center.",
    "how_it_works.step1_b1": "✓ Real-time distance and route status",
    "how_it_works.step1_b2": "✓ Crop-wise storage capacity check",
    "how_it_works.step1_b3": "✓ Alternative mandi routing alerts",
    "how_it_works.step2_title": "2. Slot Booking & Idempotent Token Issuance",
    "how_it_works.step2_subtitle": "Precise time allocation based on crop, quantity, and vehicle type",
    "how_it_works.step2_desc": "Farmers enter expected crop quantity and vehicle details. A concurrent transaction generates an assured token like A-142 and arrival window.",
    "how_it_works.step2_b1": "✓ 22-language voice booking supported",
    "how_it_works.step2_b2": "✓ Instant SMS confirmation on basic phones",
    "how_it_works.step2_b3": "✓ Secure digital gate pass code",
    "how_it_works.step3_title": "3. Live Radar Queue Tracking & Arrival",
    "how_it_works.step3_subtitle": "Live status tracking from home and on-time arrival notifications",
    "how_it_works.step3_desc": "Farmers track the queue from home (e.g. A-136 currently serving, 4 ahead). Upon arriving at the gate, the gatekeeper logs entry to activate the token.",
    "how_it_works.step4_title": "4. Quality Grading & Weighbridge Slip",
    "how_it_works.step4_subtitle": "Moisture analyzer reading and digital scale entry",
    "how_it_works.step4_desc": "Procurement officers record moisture % (e.g. 14.2%) and quality grade. The digital weighbridge captures net quintals, instantly generating a digital receipt sent to the farmer's mobile.",
    "how_it_works.step5_title": "5. PFMS Direct Bank DBT & CAG Audit Trail",
    "how_it_works.step5_subtitle": "Direct payment within 24-48 hours and transparent cryptographic audit log",
    "how_it_works.step5_desc": "Approved MSP amounts transfer directly to the farmer's Aadhaar-linked bank account via PFMS. A cryptographic record is permanently secured in the audit trail.",
    "how_it_works.cta_heading": "Ready to experience transparent procurement?",
    "how_it_works.cta_subtitle": "Enter your mobile number today or run the live presentation demo.",
