    "for_government.feat_alerts_title": "ਸੁਰੱਖਿਆ ਅਲਰਟ",
    "for_government.feat_alerts_desc": "ਅਸਧਾਰਨ ਪੈਟਰਨ ਜਿਵੇਂ ਇੱਕ ਹੀ ਵਾਹਨ ਦਾ ਵਾਰ-ਵਾਰ ਆਉਣਾ ਸਿਸਟਮ ਦੁਆਰਾ ਤੁਰੰਤ ਫੜਿਆ ਜਾਂਦਾ ਹੈ।",
