    "how_it_works.step1_subtitle": "જીપીએસ આધારિત શોધ અને મંડી લોડ બેલેન્સિંગ",
    "how_it_works.step1_desc": "ખેડૂતો જિલ્લાના તમામ સક્રિય કેન્દ્રોની યાદી જોઈને ઝડપી કેન્દ્ર પસંદ કરે છે.",
