    "how_it_works.step1_b3": "✓ વૈકલ્પિક મંડી રૂટિંગ એલર્ટ",
    "how_it_works.step2_title": "૨. સ્લોટ બુકિંગ અને ડિજિટલ ટોકન",
    "how_it_works.step2_subtitle": "પાક, જથ્થો અને વાહન અનુસાર ચોક્કસ સમય ફાળવણી",
    "how_it_works.step2_desc": "ખેડૂત પાકનો જથ્થો અને વાહનની માહિતી દાખલ કરે છે અને ટોકન A-142 મળે છે.",
