    "how_it_works.step3_desc": "ખેડૂત ઘરેથી લાઇવ લાઇન જોઈ શકે છે અને ગેટ પર પહોંચતા જ એન્ટ્રી થાય છે.",
    "how_it_works.step4_title": "૪. ગુણવત્તા ચકાસણી અને ડિજિટલ તોલ",
    "how_it_works.step4_subtitle": "ભેજ પરીક્ષણ અને ઇલેક્ટ્રોનિક કાંટા એન્ટ્રી",
    "how_it_works.step4_desc": "અધિકારી ભેજ અને ગ્રેડ નોંધીને ડિજિટલ રસીદ આપે છે.",
