    "for_centers.feat_weighing_desc": "इलेक्ट्रॉनिक कांटे से सीधा डेटा फेच और डिजिटल स्वीकृति पर्ची, बिना किसी मानवीय त्रुटि अथवा कागजी झंझट के।",
