    "for_centers.feat_audit_desc": "प्रत्येक प्रविष्टि अधिकारी की डिजिटल आईडी और टाइमस्टैम्प के साथ सुरक्षित रहती है, जिससे ऑडिट में 100% प्रमाणिकता रहती है।",
