    "for_centers.subtitle": "सटीक आवक पूर्वानुमान, थ्रूपुट पेसिंग, डिजिटल वजन प्रविष्टि और विवाद-मुक्त दैनिक खरीद का पूर्ण नियंत्रण।",
    "for_centers.feat_pacing_title": "कतार थ्रूपुट पेसिंग (Queue Pacing)",
    "for_centers.feat_pacing_desc": "कांटों की वास्तविक गति के अनुसार किसानों को मंडी बुलाया जाता है, जिससे यार्ड में वाहनों का जाम नहीं लगता।",
